      PROGRAM CREADOCCC++----------------------------------------------------------------------------CC+1   BESCHREIBUNG :C       CREADOC ist ein einfaches "Dokumentier-Programm". Es extrahiert aus denC       Sourcefiles mit der Endung ".f" die im Programmkopf enthaltene Dokumen-C       tation und schreibt sie in ein neues File mit dem Namen "creadoc.txt".CC       Jeder "Programmkopf" wird mit den Zeichen "C++" (Anfang) und "C--"C       (Ende) in den Spalten 1 bis 3 gekennzeichnet. Dazwischen werden einC       oder mehrere Abschnitte erwartet; diese sind durch die Zeichen "C+"C       (Anfang) und "C-" (Ende) in den Spalten 1 und 2 definiert. Beim Ab-C       schnitt-Anfang wird ab Spalte 4 ein Titel (z.B. "BESCHREIBUNG :") er-C       wartet. Ist nun zwischen "C+" und C-" mindestens eine weitere ZeileC       enthalten, wird der Abschnitt in die Doku uebernommen und andernfallsC       ueberlesen.CC       Als Beispiel dient dieses Programm selber (creadoc.f).C-1C+2   PARAMETER :C-2C+3   GERUFENE SUBROUTINEN/FUNCTIONS :C       UpperCase, DeleteFileC-3C+4   CALL-BEISPIEL :C-4C+5   BEMERKUNGEN :C-5C+6   COPYRIGHT :C       Nur fuer nichtkommerzielle Nutzung freigegeben !C-6C+7   HARDWARE :C       GEPARD 68000, 1 Sony-Laufwerk 3.5", 1.5MB RAM, 30 MB Harddisk,C       80-Zeichen-Karte, Seriell-Parallel-Karte MTH3C-7C+8   BETRIEBSSYSTEM/VERSION, COMPILER/VERSION :C       Professional OS-9 V2.1, RTF-Fortran V2.14C-8C+9   AUTOR(EN), ADRESSE, KURZZEICHEN :C       EGA : Andreas Eggenberger, Butzenstrasse 30,    Tel-P:     01/761 42 27C             CH-8910 Affoltern a/A                     Tel-G:     01/249 24 96C-9C+A   DATUM, AENDERUNGEN, VERSION :C       02.04.88/EGA V1.0 UrversionC-AC------------------------------------------------------------------------------C      IMPLICIT NONEC      INTEGER       LEN      INTEGER       fnpos, fnlen, tlen, UpperCase      INTEGER       i, j, k, iret, length, level, lcntrC      LOGICAL       openedC      CHARACTER*132 line, s, str, dash, titel      CHARACTER*40  filename, dirfile, listfile      CHARACTER*3   s3      CHARACTER*4   leftCC------------------------------------------------------------------------------C      dirfile  = 'creadoc.tmp'      listfile = 'creadoc.txt'      fnpos    = 54                ! Filename Position im "dir"-Output      left     = ' '               ! linker Rand      opened   = .FALSE.C      DO i = 1, LEN(dash)        dash(i:i) = '-'      END DOC      CALL DeleteFile (dirfile)    ! Weg damit, falls ueberhaupt vorhanden      CALL shell ('dir -eadu *.f >'//dirfile, iret)  ! Programm-Verzeichnis      OPEN (10, FILE=dirfile)C      DO FOREVER          READ (10, 9000, END=900) str          length = LEN (str(:-1))          filename = str (fnpos:length)          fnlen = length - fnpos + 1          TYPE *, 'Processing file ' // filename(:fnlen)          OPEN (12, FILE=filename(:fnlen))          level = 0          DO FOREVER            READ (12, 9000, END=500) line            s3 = line(1:3)            j = UpperCase (s3)            IF (s3 .EQ. 'C--') THEN              ! Doku-Ende :              IF (level .GT. 0 .AND. opened) WRITE (20, 8000) CHAR(12)  ! <FF>              level = 0              lcntr = 0            ELSE              k = LEN (line(:-1))              IF (s3(1:2) .EQ. 'C+') THEN                IF (s3 .NE. 'C++') THEN          ! Doku-Anfang :                  level = level + 1                  i = 4                  DO WHILE (line(i:i) .LE. ' ' .AND. i .LT. k)                    i = i + 1                  END DO                  titel = line(i:k)                  tlen  = k - i + 1                  lcntr = 0                END IF              ELSE IF (s3(1:2) .EQ. 'C-') THEN                lcntr = 0              ELSE IF (level .GT. 0) THEN       ! Kommentar (Doku) - Zeile                lcntr = lcntr + 1                IF (lcntr .LE. 1) THEN                  IF (.NOT. opened) THEN                    CALL DeleteFile (listfile)  ! 'listfile' darf nicht existieren		    TYPE *, 'Creating file '//listfile(:LEN(listfile(:-1)))                    OPEN (20, FILE=listfile)                    opened = .TRUE.                  END IF                  IF (level .LE. 1) THEN                    WRITE (20, 8000) ' '                    WRITE (20, 8000) left // dash(:76)                    WRITE (20, 8000) left // 'Dokumentation aus ' //     1                'Fortran-Sourcefile "' // filename(:fnlen) //'"'                    WRITE (20, 8000) left // dash(:76)                    WRITE (20, 8000) ' '                  END IF                  WRITE (20, 8000) ' '                  WRITE (20, 8000) left // titel(:tlen)                  WRITE (20, 8000) left // dash(:tlen)                  WRITE (20, 8000) ' '                END IF                WRITE (20, 8000) left // line(5:k)              END IF            END IF          END DO500       CONTINUE          CLOSE (12)      END DOC900   CONTINUE      CLOSE (10)      CALL DeleteFile (dirfile)    ! Das brauchen wir nun nicht mehr      IF (opened) CLOSE (20)C8000  FORMAT (A)9000  FORMAT (A)C      ENDCC------------------------------------------------------------------------------C      INTEGER FUNCTION UpperCase (str)      INTEGER       i, LEN      CHARACTER*(*) str      CHARACTER*1   ch      length = LEN (str)      DO i = 1, length          ch = str(i:i)          IF (ch .GE. 'a' .AND. ch .LE. 'z') str(i:i) = CHAR (ICHAR(ch)-32)      END DO      UpperCase = length      RETURN      ENDCC------------------------------------------------------------------------------C      SUBROUTINE DeleteFile (fn)      IMPLICIT NONE      INTEGER       LEN, length, iret      CHARACTER*(*) fnC      length = LEN (fn(:-1))      OPEN (2, FILE=fn(:length))             ! File muss zum loeschen auf jeden      CLOSE (2)                              ! Fall existieren, da sonst      CALL shell ('del '//fn(:length), iret) ! Fehlermeldungen moeglich !C      RETURN      END